const styles=new CSSStyleSheet;styles.replaceSync('/*\n * Copyright 2022 The Chromium Authors. All rights reserved.\n * Use of this source code is governed by a BSD-style license that can be\n * found in the LICENSE file.\n */\n\ndevtools-request-headers-category {\n  --override-header-highlight-background-color: #ffff78;\n}\n\n.-theme-with-dark-background devtools-request-headers-category,\n:host-context(.-theme-with-dark-background) devtools-request-headers-category {\n  --override-header-highlight-background-color: #4c4c33;\n}\n\n.header {\n  background-color: var(--sys-color-surface1);\n  border-bottom: 1px solid var(--sys-color-divider);\n  border-top: 1px solid var(--sys-color-divider);\n  line-height: 25px;\n  padding: 0 5px;\n}\n\n.header::marker {\n  color: rgb(110 110 110); /* stylelint-disable-line plugin/use_theme_colors */\n  /* See: crbug.com/1152736 for color variable migration. */\n  font-size: 11px;\n  line-height: 1;\n}\n\n.header:focus {\n  background-color: var(--sys-color-state-header-hover);\n}\n\ndetails[open] .header-count {\n  display: none;\n}\n\ndetails .hide-when-closed {\n  display: none;\n}\n\ndetails[open] .hide-when-closed {\n  display: block;\n}\n\ndetails summary input {\n  vertical-align: middle;\n}\n\n.row {\n  display: flex;\n  line-height: 20px;\n  padding-left: 8px;\n  gap: 12px;\n  user-select: text;\n}\n\ndiv.raw-headers-row {\n  display: block;\n}\n\n.row:first-of-type {\n  margin-top: 2px;\n}\n\n.row:last-child {\n  margin-bottom: 10px;\n}\n\n.header-name {\n  color: var(--color-text-primary);\n  font-weight: 400;\n  width: 30%;\n  min-width: 160px;\n  max-width: 240px;\n  flex-shrink: 0;\n  text-transform: capitalize;\n}\n\n.header-value {\n  word-break: break-all;\n  display: flex;\n  align-items: center;\n  gap: 2px;\n}\n\n.green-circle::before,\n.red-circle::before,\n.yellow-circle::before {\n  content: "";\n  display: inline-block;\n  width: 12px;\n  height: 12px;\n  border-radius: 6px;\n  vertical-align: text-top;\n  margin-right: 2px;\n}\n\n.green-circle::before {\n  background-color: var(--color-accent-green);\n}\n\n.red-circle::before {\n  background-color: var(--color-accent-red);\n}\n\n.yellow-circle::before {\n  background-color: var(--issue-color-yellow);\n}\n\n.status-with-comment {\n  color: var(--color-text-secondary);\n}\n\n.raw-headers {\n  font-family: var(--source-code-font-family);\n  font-size: var(--source-code-font-size);\n  white-space: pre-wrap;\n  word-break: break-all;\n}\n\n.link,\n.devtools-link {\n  color: var(--color-link);\n  text-decoration: underline;\n  cursor: pointer;\n  outline-offset: 2px;\n}\n\n.inline-icon {\n  vertical-align: middle;\n}\n\n.header-grid-container {\n  display: inline-grid;\n  grid-template-columns: 156px 50px 1fr;\n  grid-gap: 4px;\n  /* Make this fit into the same line as the summary marker */\n  width: calc(100% - 15px);\n}\n\n.header-grid-container div:last-child {\n  text-align: right;\n}\n\n.header .devtools-link {\n  color: var(--color-text-primary);\n}\n\nx-link { /* stylelint-disable-line selector-type-no-unknown */\n  position: relative;\n}\n\nx-link .inline-icon { /* stylelint-disable-line selector-type-no-unknown */\n  padding-right: 3px;\n}\n\n.purple.dot::before {\n  background-color: var(--color-purple-bright);\n  content: url("Images/empty.svg");\n  width: 6px;\n  height: 6px;\n  border-radius: 50%;\n  outline: 1px solid var(--icon-gap-toolbar);\n  left: 9px;\n  position: absolute;\n  top: 11px;\n  z-index: 1;\n}\n\nsummary label {\n  color: var(--color-text-secondary);\n}\n\nsummary label:hover {\n  color: var(--color-text-primary);\n}\n\n/*# sourceURL=RequestHeadersView.css */\n');export default styles;